head.script:
// ================================================================
// 전역 변수 및 상수 정의
// ================================================================
scwin.LOGIN_USER_ID = "";
scwin.PJT_ID = "";

// ================================================================
// 페이지 생명주기 함수
// ================================================================

/**
 * 페이지 로드 시 초기화
 * @description 사용자 정보 및 프로젝트 정보를 설정하고 WBS 목록을 조회합니다.
 */
scwin.onpageload = function () {
    var usrId = $p.getComponentById("mf_pg_header").getWindow().scwin.USER_ID;
    var selPjtId = $p.getParentWindow().scwin.SEL_PJT_ID;

    if (usrId && selPjtId) {
        scwin.LOGIN_USER_ID = usrId;
        scwin.PJT_ID = selPjtId;
    }

    // 검색 조건 초기화 및 WBS 조회
    dmp_wbsVo.set("pjtId", scwin.PJT_ID);
    scwin.btn_search_onclick();
};

// ================================================================
// 이벤트 핸들러 함수
// ================================================================

/**
 * 조회 버튼 클릭 이벤트
 * @description 페이지 번호를 초기화하고 WBS 목록을 조회합니다.
 * @param {Event} e - 클릭 이벤트 객체
 */
scwin.btn_search_onclick = function (e) {
    dmp_wbsVo.set("pageIndex", "1");
    pgl_wbsList.setSelectedIndex(1);
    $c.sbm.execute(sbm_selectWbsVoList);
};

/**
 * 페이지 번호 클릭 이벤트
 * @description 선택한 페이지로 이동하여 WBS 목록을 조회합니다.
 * @param {number} idx - 선택된 페이지 번호
 */
scwin.pgl_wbsList_onclick = function (idx) {
    dmp_wbsVo.set("pageIndex", idx);
    $c.sbm.execute(sbm_selectWbsVoList);
};

/**
 * 신규 등록 버튼 클릭 이벤트
 * @description WBS 신규 업무 등록 팝업을 호출합니다.
 * @param {Event} e - 클릭 이벤트 객체
 */
scwin.btn_new_onclick = function (e) {
    var popupData = {
        "type": "json",
        "name": "params",
        "data": {
            "pjtId": scwin.PJT_ID,
            "userId": scwin.LOGIN_USER_ID,
            "popupType": "new"
        }
    };

    const popupWidth = 800;
    const popupHeight = 800;
    const centeredPosition = scwin.getCenteredPopupPosition(popupWidth, popupHeight);

    const options = {
        id: "wbs_new",
        type: "wframePopup",
        width: popupWidth + "px",
        height: popupHeight + "px",
        top: centeredPosition.top,
        left: centeredPosition.left,
        popupName: "업무 생성",
        modal: true,
        closeAction: "scwin.popup_closeAction",
        dataObject: popupData
    };

    $p.openPopup("/InsWebApp/ui/wbs/WbsDetail.xml", options);
};

/**
 * 삭제 버튼 클릭 이벤트
 * @description 선택된 행들을 삭제합니다.
 * @param {Event} e - 클릭 이벤트 객체
 */
scwin.btn_delete_onclick = function (e) {
    let chkArrIdx = grd_list.getCheckedIndex("chk");
    if (chkArrIdx.length === 0) {
        $c.win.alert("삭제할 항목을 선택해주세요.");
        return;
    }
    dlt_wbsVoList.deleteRows(chkArrIdx);
};

/**
 * 저장 버튼 클릭 이벤트
 * @description 변경된 데이터를 서버에 저장합니다.
 * @param {Event} e - 클릭 이벤트 객체
 */
scwin.btn_save_onclick = function (e) {
    let reqObj = {
        "elData": { "wbsVoList": dlt_wbsVoList.getModifiedJSON() }
    };
    $c.sbm.execute(sbm_saveWbsVoList, reqObj);
};

/**
 * 다운로드 버튼 클릭 이벤트
 * @description 전체 데이터를 엑셀 파일로 다운로드합니다.
 * @param {Event} e - 클릭 이벤트 객체
 */
scwin.btn_down_onclick = function (e) {
    var totalCount = spn_listCnt.getLabel();

    if (totalCount === "0") {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    // 페이징 조건 백업
    var originalPageIndex = dmp_wbsVo.get("pageIndex");
    var originalPageSize = dmp_wbsVo.get("pageSize");

    // 전체 데이터 조회 설정
    dmp_wbsVo.set("pageIndex", "1");
    dmp_wbsVo.set("pageSize", totalCount);

    // 전체 데이터 조회 실행
    $c.sbm.execute(sbm_selectWbsVoListForExcel);

    // 페이징 조건 복원
    dmp_wbsVo.set("pageIndex", originalPageIndex);
    dmp_wbsVo.set("pageSize", originalPageSize);
};

/**
 * 그리드 셀 클릭 이벤트
 * @description 현재 미사용 상태입니다.
 * @param {number} rowIndex - 행 인덱스
 * @param {number} columnIndex - 컬럼 인덱스
 * @param {string} columnId - 컬럼 ID
 */
scwin.grd_list_oncellclick = function (rowIndex, columnIndex, columnId) {
    // 현재 구현 없음
};

/**
 * 그리드 셀 더블클릭 이벤트
 * @description WBS 상세 정보 팝업을 호출합니다.
 * @param {number} rowIndex - 행 인덱스
 * @param {number} columnIndex - 컬럼 인덱스
 * @param {string} columnId - 컬럼 ID
 */
scwin.grd_list_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    var rowData = dlt_wbsVoList.getRowJSON(rowIndex);
    var popupData = {
        "type": "json",
        "name": "params",
        "data": {
            "pjtId": scwin.PJT_ID,
            "popupType": "detail",
            "rowData": rowData
        }
    };

    const popupWidth = 800;
    const popupHeight = 800;
    const centeredPosition = scwin.getCenteredPopupPosition(popupWidth, popupHeight);

    const options = {
        id: "wbs_detail",
        type: "wframePopup",
        width: popupWidth + "px",
        height: popupHeight + "px",
        top: centeredPosition.top,
        left: centeredPosition.left,
        popupName: "업무 상세",
        modal: true,
        closeAction: "scwin.popup_closeAction",
        dataObject: popupData
    };

    $p.openPopup("/InsWebApp/ui/wbs/WbsDetail.xml", options);
};

// ================================================================
// 그룹핑 관련 함수
// ================================================================

/**
 * 업무 구분별 그룹핑
 * @description 설계/개발 구분으로 데이터를 그룹핑합니다.
 */
scwin.groupByTaskType = function () {
    var options = {
        sortIndex: ["taskTypeName"],
        sortOrder: [1],
        closeGroup: false,
        groupbyHeader: [{
            inputType: "expression",
            expression: 'toggle() + depthStr() + " (" + count() + " 건) "',
            align: "left",
            colSpan: "18"
        }],
        hideFooter: true
    };
    grd_list.groupby(options);
};

/**
 * 업무상태별 그룹핑
 * @description 진행중/대기/완료 상태별로 데이터를 그룹핑합니다.
 */
scwin.groupByTaskStatus = function () {
    var options = {
        sortIndex: ["taskStatus"],
        sortOrder: [1],
        closeGroup: false,
        groupbyHeader: [{
            inputType: "expression",
            expression: 'toggle() + depthStr() + " (" + count() + " 건) "',
            align: "left",
            colSpan: "18"
        }],
        hideFooter: true
    };
    grd_list.groupby(options);
};

/**
 * 지연여부별 그룹핑
 * @description 지연여부(없음/완료/지연완료/지연중/진행중)별로 데이터를 그룹핑합니다.
 */
scwin.groupByDelayStatus = function () {
    var options = {
        sortIndex: ["isLazy"],
        sortOrder: [1],
        closeGroup: false,
        groupbyHeader: [{
            inputType: "expression",
            expression: 'toggle() + depthStr() + " (" + count() + " 건) "',
            align: "left",
            colSpan: "18"
        }],
        hideFooter: true
    };
    grd_list.groupby(options);
};

/**
 * 그룹핑 초기화
 * @description 그룹핑을 해제하고 검색 조건을 초기화한 후 재조회합니다.
 * @param {Event} e - 클릭 이벤트 객체
 */
scwin.btn_clearGroupby_onclick = function (e) {
    grd_list.clearGroupby();
    dmp_wbsVo.setEmptyValue();
    dmp_wbsVo.set("pjtId", scwin.PJT_ID);
    scwin.btn_search_onclick();
};

// ================================================================
// 서브미션 콜백 함수
// ================================================================

/**
 * WBS 목록 조회 완료 콜백
 * @description 서버에서 WBS 목록 조회 완료 시 호출되는 함수입니다.
 * @param {Object} e - 응답 이벤트 객체
 */
scwin.sbm_wbsList_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    // 에러 처리
    if (elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    // 총 레코드 수 업데이트
    spn_listCnt.setLabel(elData.totalCount);

    // 데이터 가공 및 UI 표시용 필드 추가
    var wbsDataWithTaskType = elData.wbsVoList.map(function (item) {
        // 업무 구분명 추가
        item.taskTypeName = scwin.getTaskTypeName(item.isDesign);
        item.taskTypeForGrouping = item.isDesign + '|' + item.taskTypeName;

        // 지연여부 계산 및 추가
        const delayStatus = scwin.calculateDelayStatus(item.taskEt, item.taskRet, item.taskStatus);
        item.isLazy = scwin.getDelayStatusText(delayStatus);
        item.delayStatusCode = delayStatus;

        // UI 표시용 데이터 생성
        item.isTestDisplay = scwin.getTestStatusDisplay(item.isTest);
        item.isDesignDisplay = scwin.getTaskTypeDisplay(item.isDesign);

        return item;
    });

    dlt_wbsVoList.setJSON(wbsDataWithTaskType);

    // 페이징 정보 업데이트
    var totalPageCount = Math.ceil(elData.totalCount / dmp_wbsVo.get("pageSize"));
    pgl_wbsList.setCount(totalPageCount);
    spn_totalPageCount.setValue(totalPageCount);
    spn_pageIndex.setValue(dmp_wbsVo.get("pageIndex"));
    pgl_wbsList.setSelectedIndex(dmp_wbsVo.get("pageIndex"));

    // 순번 업데이트
    let num = Number(dmp_wbsVo.get("pageIndex"));
    num = (num - 1) * 10;
    grd_list.setStartRowNumber(num);

    // 그리드 스타일 적용
    scwin.setProgressStyle();
    scwin.setTaskStatusStyle();
    scwin.setTestStatusStyle();
    scwin.setDelayStatusStyle();
    scwin.setTaskTypeStyle();
};

/**
 * WBS 저장 완료 콜백
 * @description 서버에 WBS 저장 완료 시 호출되는 함수입니다.
 * @param {Object} e - 응답 이벤트 객체
 */
scwin.sbm_saveWbsVoList_submitdone = function (e) {
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader === "" || elHeader === "undefined" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    $c.win.alert("저장이 완료되었습니다.");
    scwin.btn_search_onclick();
};

/**
 * 엑셀 다운로드용 전체 데이터 조회 완료 콜백
 * @description 엑셀 다운로드용 전체 데이터 조회 완료 시 호출되는 함수입니다.
 * @param {Object} e - 응답 이벤트 객체
 */
scwin.sbm_selectWbsVoListForExcel_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader == "" || elHeader == "undefined" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    // 데이터 유효성 검증
    if (!elData.wbsVoList || elData.wbsVoList.length === 0) {
        $c.win.alert("다운로드할 데이터가 없습니다.");
        return;
    }

    // 엑셀 다운로드 실행
    var originalData = dlt_wbsVoList.getAllJSON();
    var wbsDataForExcel = elData.wbsVoList.map(function (item) {
        item.taskTypeName = scwin.getTaskTypeName(item.isDesign);
        return item;
    });
    dlt_wbsVoList.setJSON(wbsDataForExcel);

    var options = {
        fileName: "WBS_목록_" + new Date().toISOString().slice(0, 10).replace(/-/g, ""),
        useStyle: true,
        headerFontBold: true,
        bodyFontBold: false,
        type: 1,
        trim: 1,
        removeColumns: "0,1,2,4,7,9,14,17,18,21,22",
        processMsg: "엑셀 파일을 생성하고 있습니다...",
        timeout: 60000,
        checkInterval: 1000,
        onSuccessCallback: function () {
            $c.win.alert("엑셀 파일 다운로드가 완료되었습니다.");
            dlt_wbsVoList.setJSON(originalData);
            scwin.btn_search_onclick();
        },
        onFailureCallback: function () {
            $c.win.alert("엑셀 파일 다운로드에 실패했습니다.");
            dlt_wbsVoList.setJSON(originalData);
            scwin.btn_search_onclick();
        }
    };

    grd_list.advancedExcelDownload(options);
};

/**
 * 팝업 닫기 시 재조회 처리
 * @description 팝업 창이 닫힐 때 WBS 목록을 재조회합니다.
 * @param {String} argRuntimeID - 팝업의 실행 ID
 * @param {Object} argJsnInfo - 팝업 닫힘 시 전달된 정보
 * @returns {Boolean} 팝업 닫기 여부
 */
scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    scwin.btn_search_onclick();
    return true;
};

// ================================================================
// 유틸리티 함수
// ================================================================

/**
 * 팝업 중앙 정렬 위치 계산
 * @description 팝업을 화면 중앙에 위치시키기 위한 좌표를 계산합니다.
 * @param {number} popupWidth - 팝업의 너비 (px)
 * @param {number} popupHeight - 팝업의 높이 (px)
 * @returns {Object} 팝업의 left, top 스타일 값을 포함한 객체
 */
scwin.getCenteredPopupPosition = function (popupWidth, popupHeight) {
    const scrollX = window.scrollX || document.documentElement.scrollLeft;
    const scrollY = window.scrollY || document.documentElement.scrollTop;
    const viewportWidth = window.innerWidth || document.documentElement.clientWidth;
    const viewportHeight = window.innerHeight || document.documentElement.clientHeight;

    const left = scrollX + (viewportWidth - popupWidth) / 2;
    const top = scrollY + (viewportHeight - popupHeight) / 2;

    return { left: left + "px", top: top + "px" };
};

/**
 * 업무 구분명 반환 함수
 * @description 업무 구분 코드에 따른 구분명을 반환합니다.
 * @param {string|number} isDesign - 업무 구분 (0: 개발, 1: 설계)
 * @returns {string} 업무 구분명
 */
scwin.getTaskTypeName = function (isDesign) {
    if (isDesign === "1" || isDesign === 1) {
        return "설계";
    } else if (isDesign === "0" || isDesign === 0) {
        return "개발";
    } else {
        return "미분류";
    }
};

/**
 * 업무 구분 표시 텍스트 반환
 * @description UI 표시용 업무 구분 텍스트를 반환합니다.
 * @param {string|number} isDesign - 업무 구분
 * @returns {string} 표시 텍스트
 */
scwin.getTaskTypeDisplay = function (isDesign) {
    return scwin.getTaskTypeName(isDesign);
};

/**
 * 테스트여부 표시 텍스트 반환
 * @description UI 표시용 테스트여부 기호를 반환합니다.
 * @param {string} isTest - 테스트여부 (0: 미테스트, 1: 테스트완료)
 * @returns {string} 표시 문자
 */
scwin.getTestStatusDisplay = function (isTest) {
    if (isTest === "0") {
        return "●"; // 빨간색 원
    } else if (isTest === "1") {
        return "●"; // 녹색 원
    } else {
        return "○"; // 빈 원
    }
};

// ================================================================
// 스타일 적용 함수들
// ================================================================

/**
 * 진척률별 프로그래스 바 스타일 적용
 * @description 진척률에 따라 그리드 셀에 프로그래스 바 스타일을 적용합니다.
 */
scwin.setProgressStyle = function () {
    const rowCount = dlt_wbsVoList.getTotalRow();
    for (let i = 0; i < rowCount; i++) {
        const rate = dlt_wbsVoList.getCellData(i, "taskRate");
        if (rate) {
            const progressValue = Math.min(Math.max(Number(rate), 0), 1);
            const progressPercent = Math.round(progressValue * 100);

            // 프로그래스 바 색상 결정
            let progressColor;
            if (progressPercent < 30) {
                progressColor = '#ff4444';  // 빨간색
            } else if (progressPercent < 70) {
                progressColor = '#ffaa00';  // 주황색
            } else {
                progressColor = '#00aa00';  // 녹색
            }

            const progressStyle = `
                background: linear-gradient(to right, 
                    ${progressColor} 0%, 
                    ${progressColor} ${progressPercent}%, 
                    #f0f0f0 ${progressPercent}%, 
                    #f0f0f0 100%);
                text-align: center;
                font-weight: bold;
                color: #333;
            `;

            grd_list.setCellStyle(i, "taskRate", progressStyle);
        }
    }
};

/**
 * 업무상태별 스타일 적용
 * @description 업무상태(대기/진행중/완료)에 따라 배경색을 다르게 적용합니다.
 */
scwin.setTaskStatusStyle = function () {
    const rowCount = dlt_wbsVoList.getTotalRow();
    for (let i = 0; i < rowCount; i++) {
        const status = dlt_wbsVoList.getCellData(i, "taskStatus");
        let statusStyle = "";

        switch (status) {
            case "대기":
                statusStyle = "background-color: #fff3cd; color: #856404;";
                break;
            case "진행중":
                statusStyle = "background-color: #d1ecf1; color: #0c5460;";
                break;
            case "완료":
                statusStyle = "background-color: #d4edda; color: #155724;";
                break;
            default:
                statusStyle = "background-color: #f8f9fa; color: #6c757d;";
        }

        grd_list.setCellStyle(i, "taskStatus", statusStyle);
    }
};

/**
 * 테스트여부 스타일 적용
 * @description 테스트 완료 여부에 따라 원(●) 색상을 다르게 적용합니다.
 */
scwin.setTestStatusStyle = function () {
    const rowCount = dlt_wbsVoList.getTotalRow();
    for (let i = 0; i < rowCount; i++) {
        const isTest = dlt_wbsVoList.getCellData(i, "isTest");
        let testStyle = "text-align: center; font-size: 16px; font-weight: bold;";

        if (isTest === "1") {
            testStyle += "color: #28a745;";  // 녹색: 테스트 완료
        } else if (isTest === "0") {
            testStyle += "color: #dc3545;";  // 빨간색: 미테스트
        } else {
            testStyle += "color: #6c757d;";  // 회색: 불명
        }

        grd_list.setCellStyle(i, "isTestDisplay", testStyle);
    }
};

/**
 * 지연여부 스타일 적용
 * @description 지연상태에 따라 텍스트 색상을 다르게 적용합니다.
 */
scwin.setDelayStatusStyle = function () {
    const rowCount = dlt_wbsVoList.getTotalRow();
    for (let i = 0; i < rowCount; i++) {
        const delayStatusCode = dlt_wbsVoList.getCellData(i, "delayStatusCode");
        let delayStyle = "font-weight: bold;";

        switch (delayStatusCode) {
            case "0":  // 없음
                delayStyle += "color: #6c757d;";
                break;
            case "1":  // 완료
                delayStyle += "color: #28a745;";
                break;
            case "2":  // 지연완료
                delayStyle += "color: #fd7e14;";
                break;
            case "3":  // 지연중
                delayStyle += "color: #dc3545;";
                break;
            case "4":  // 진행중
                delayStyle += "color: #007bff;";
                break;
            default:
                delayStyle += "color: #6c757d;";
        }

        grd_list.setCellStyle(i, "isLazy", delayStyle);
    }
};

/**
 * 업무구분 스타일 적용
 * @description 업무구분(설계/개발)에 따라 배경색을 다르게 적용합니다.
 */
scwin.setTaskTypeStyle = function () {
    const rowCount = dlt_wbsVoList.getTotalRow();
    for (let i = 0; i < rowCount; i++) {
        const isDesign = dlt_wbsVoList.getCellData(i, "isDesign");
        let typeStyle = "text-align: center; font-weight: bold;";

        if (isDesign === "1") {
            typeStyle += "background-color: #e7f3ff; color: #0056b3;";  // 파란색 계열: 설계
        } else if (isDesign === "0") {
            typeStyle += "background-color: #fff2e7; color: #d63384;";  // 주황색 계열: 개발
        } else {
            typeStyle += "background-color: #f8f9fa; color: #6c757d;";  // 회색: 미분류
        }

        grd_list.setCellStyle(i, "taskTypeName", typeStyle);
    }
};

// ================================================================
// 비즈니스 로직 계산 함수들
// ================================================================

/**
 * 지연여부 상태 계산
 * @description 완료예정일, 실제완료일, 업무상태를 기반으로 지연여부를 계산합니다.
 * @param {string} taskEt - 완료예정일 (YYYY-MM-DD 형식)
 * @param {string} taskRet - 실제완료일 (YYYY-MM-DD 형식)
 * @param {string} taskStatus - 업무상태 (대기/진행중/완료)
 * @returns {string} 지연여부 코드 (0:없음, 1:완료, 2:지연완료, 3:지연중, 4:진행중)
 */
scwin.calculateDelayStatus = function (taskEt, taskRet, taskStatus) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);  // 시간을 00:00:00으로 설정하여 날짜만 비교

    // 날짜 문자열을 Date 객체로 변환
    const endDate = taskEt ? new Date(taskEt) : null;
    const realEndDate = taskRet ? new Date(taskRet) : null;

    // 완료상태인 경우
    if (taskStatus === "완료") {
        if (realEndDate && endDate) {
            // 실제완료일이 완료예정일보다 늦은 경우 지연완료
            return realEndDate > endDate ? "2" : "1";
        }
        return "1";  // 완료
    }

    // 미완료 상태인 경우 (대기, 진행중)
    if (taskStatus === "진행중") {
        if (endDate && today > endDate) {
            return "3";  // 지연중
        }
        return "4";  // 진행중
    }

    return "0";  // 없음 (대기 상태 등)
};

/**
 * 지연여부 텍스트 반환
 * @description 지연여부 코드에 따른 표시 텍스트를 반환합니다.
 * @param {string} delayStatusCode - 지연여부 코드
 * @returns {string} 지연여부 텍스트
 */
scwin.getDelayStatusText = function (delayStatusCode) {
    const delayStatusMap = {
        "0": "없음",
        "1": "완료",
        "2": "지연완료", 
        "3": "지연중",
        "4": "진행중"
    };

    return delayStatusMap[delayStatusCode] || "불명";
};

/**
 * 날짜 형식 검증
 * @description YYYY-MM-DD 형식의 날짜 문자열이 유효한지 검증합니다.
 * @param {string} dateString - 검증할 날짜 문자열
 * @returns {boolean} 유효한 날짜 형식 여부
 */
scwin.isValidDateFormat = function (dateString) {
    if (!dateString || typeof dateString !== 'string') {
        return false;
    }

    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (!dateRegex.test(dateString)) {
        return false;
    }

    const date = new Date(dateString);
    const [year, month, day] = dateString.split('-').map(Number);

    return date.getFullYear() === year && 
           date.getMonth() === month - 1 && 
           date.getDate() === day;
};

/**
 * 진척률 유효성 검증
 * @description 진척률 값이 0-1 사이의 유효한 값인지 검증합니다.
 * @param {string|number} rate - 검증할 진척률 값
 * @returns {boolean} 유효한 진척률 여부
 */
scwin.isValidProgressRate = function (rate) {
    if (rate === null || rate === undefined || rate === '') {
        return true;  // 빈 값은 허용
    }

    const numRate = Number(rate);
    return !isNaN(numRate) && numRate >= 0 && numRate <= 1;
};

// ================================================================
// 데이터 검증 및 헬퍼 함수들
// ================================================================

/**
 * 업무 데이터 유효성 검증
 * @description WBS 업무 데이터의 필수 필드 및 형식을 검증합니다.
 * @param {Object} taskData - 검증할 업무 데이터 객체
 * @returns {Object} 검증 결과 (isValid, errorMessages 포함)
 */
scwin.validateTaskData = function (taskData) {
    const errors = [];
    const result = { isValid: true, errorMessages: [] };

    // 필수 필드 검증
    if (!taskData.taskName || taskData.taskName.trim() === '') {
        errors.push('업무명은 필수입력 항목입니다.');
    }

    if (!taskData.taskStatus) {
        errors.push('업무상태는 필수선택 항목입니다.');
    }

    if (!taskData.pjtId) {
        errors.push('프로젝트ID는 필수 항목입니다.');
    }

    // 날짜 형식 검증
    if (taskData.taskSt && !scwin.isValidDateFormat(taskData.taskSt)) {
        errors.push('시작예정일의 형식이 올바르지 않습니다. (YYYY-MM-DD)');
    }

    if (taskData.taskEt && !scwin.isValidDateFormat(taskData.taskEt)) {
        errors.push('완료예정일의 형식이 올바르지 않습니다. (YYYY-MM-DD)');
    }

    if (taskData.taskRst && !scwin.isValidDateFormat(taskData.taskRst)) {
        errors.push('실제시작일의 형식이 올바르지 않습니다. (YYYY-MM-DD)');
    }

    if (taskData.taskRet && !scwin.isValidDateFormat(taskData.taskRet)) {
        errors.push('실제완료일의 형식이 올바르지 않습니다. (YYYY-MM-DD)');
    }

    // 날짜 논리 검증
    if (taskData.taskSt && taskData.taskEt) {
        if (new Date(taskData.taskSt) > new Date(taskData.taskEt)) {
            errors.push('시작예정일은 완료예정일보다 이전이어야 합니다.');
        }
    }

    if (taskData.taskRst && taskData.taskRet) {
        if (new Date(taskData.taskRst) > new Date(taskData.taskRet)) {
            errors.push('실제시작일은 실제완료일보다 이전이어야 합니다.');
        }
    }

    // 진척률 검증
    if (!scwin.isValidProgressRate(taskData.taskRate)) {
        errors.push('진척률은 0~100% 사이의 값이어야 합니다.');
    }

    // 업무상태와 진척률 일관성 검증
    if (taskData.taskStatus === "완료" && taskData.taskRate !== "1") {
        errors.push('완료 상태인 업무는 진척률이 100%여야 합니다.');
    }

    // 업무구분 검증
    if (taskData.isDesign && !["0", "1"].includes(taskData.isDesign)) {
        errors.push('업무구분 값이 올바르지 않습니다.');
    }

    // 테스트여부 검증
    if (taskData.isTest && !["0", "1"].includes(taskData.isTest)) {
        errors.push('테스트여부 값이 올바르지 않습니다.');
    }

    // 결과 반환
    result.isValid = errors.length === 0;
    result.errorMessages = errors;

    return result;
};

/**
 * 업무명 중복 검증
 * @description 동일한 프로젝트 내에서 업무명이 중복되는지 검증합니다.
 * @param {string} taskName - 검증할 업무명
 * @param {string} currentTaskId - 현재 업무 ID (수정 시 자기 자신 제외)
 * @returns {boolean} 중복 여부 (true: 중복됨, false: 중복 안됨)
 */
scwin.isDuplicateTaskName = function (taskName, currentTaskId) {
    if (!taskName) return false;

    const totalRows = dlt_wbsVoList.getTotalRow();

    for (let i = 0; i < totalRows; i++) {
        const rowTaskName = dlt_wbsVoList.getCellData(i, "taskName");
        const rowTaskId = dlt_wbsVoList.getCellData(i, "taskId");

        if (rowTaskName === taskName && rowTaskId !== currentTaskId) {
            return true;
        }
    }

    return false;
};

/**
 * 숫자 형식으로 변환
 * @description 문자열을 숫자로 안전하게 변환합니다.
 * @param {string|number} value - 변환할 값
 * @param {number} defaultValue - 변환 실패 시 기본값
 * @returns {number} 변환된 숫자값
 */
scwin.toNumber = function (value, defaultValue) {
    defaultValue = defaultValue || 0;

    if (value === null || value === undefined || value === '') {
        return defaultValue;
    }

    const numValue = Number(value);
    return isNaN(numValue) ? defaultValue : numValue;
};

/**
 * 문자열 안전 처리
 * @description null, undefined를 빈 문자열로 변환합니다.
 * @param {*} value - 변환할 값
 * @returns {string} 문자열로 변환된 값
 */
scwin.toString = function (value) {
    if (value === null || value === undefined) {
        return '';
    }
    return String(value);
};

/**
 * 날짜 포맷팅
 * @description Date 객체를 YYYY-MM-DD 형식의 문자열로 변환합니다.
 * @param {Date} date - 포맷팅할 Date 객체
 * @returns {string} YYYY-MM-DD 형식의 날짜 문자열
 */
scwin.formatDate = function (date) {
    if (!date || !(date instanceof Date) || isNaN(date.getTime())) {
        return '';
    }

    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');

    return `${year}-${month}-${day}`;
};

/**
 * 현재 날짜 반환
 * @description 현재 날짜를 YYYY-MM-DD 형식으로 반환합니다.
 * @returns {string} 오늘 날짜 (YYYY-MM-DD)
 */
scwin.getCurrentDate = function () {
    return scwin.formatDate(new Date());
};

/**
 * 그리드 스타일 초기화
 * @description 그리드의 모든 셀 스타일을 초기화합니다.
 */
scwin.resetGridStyles = function () {
    const rowCount = dlt_wbsVoList.getTotalRow();
    const columnCount = grd_list.getColumns().length;

    for (let i = 0; i < rowCount; i++) {
        for (let j = 0; j < columnCount; j++) {
            grd_list.setCellStyle(i, j, '');
        }
    }
};

/**
 * 검색 조건 유효성 검증
 * @description 검색 조건의 형식이 올바른지 검증합니다.
 * @returns {boolean} 검색 조건 유효성 여부
 */
scwin.validateSearchConditions = function () {
    const scTaskId = dmp_wbsVo.get("scTaskId");
    const scTaskName = dmp_wbsVo.get("scTaskName");
    const scTaskAsi = dmp_wbsVo.get("scTaskAsi");

    // 업무ID는 숫자만 허용 (빈 값은 허용)
    if (scTaskId && !/^\d*$/.test(scTaskId)) {
        $c.win.alert("업무ID는 숫자만 입력 가능합니다.");
        return false;
    }

    // 업무명 길이 제한 (100자)
    if (scTaskName && scTaskName.length > 100) {
        $c.win.alert("업무명은 100자를 초과할 수 없습니다.");
        return false;
    }

    // 담당자명 길이 제한 (50자)
    if (scTaskAsi && scTaskAsi.length > 50) {
        $c.win.alert("업무담당자는 50자를 초과할 수 없습니다.");
        return false;
    }

    return true;
};

/**
 * 로딩 표시 제어
 * @description 데이터 로딩 중 표시를 제어합니다.
 * @param {boolean} show - 표시 여부 (true: 보이기, false: 숨기기)
 */
scwin.showLoadingIndicator = function (show) {
    if (show) {
        // 로딩 표시 (웹스퀘어 프레임워크의 기본 로딩 사용)
        $c.util.showProgressBar();
    } else {
        // 로딩 숨기기
        $c.util.hideProgressBar();
    }
};

/**
 * 에러 메시지 표시
 * @description 일관된 형식으로 에러 메시지를 표시합니다.
 * @param {string} title - 에러 제목
 * @param {string|Array} messages - 에러 메시지(들)
 */
scwin.showErrorMessages = function (title, messages) {
    let errorText = title || "오류가 발생했습니다.";

    if (Array.isArray(messages)) {
        errorText += "\n\n" + messages.join("\n");
    } else if (messages) {
        errorText += "\n\n" + messages;
    }

    $c.win.alert(errorText);
};

/**
 * 디버그 로그 출력
 * @description 개발/디버깅 시 콘솔에 로그를 출력합니다.
 * @param {string} message - 로그 메시지
 * @param {*} data - 로그에 포함할 데이터 (선택사항)
 */
scwin.debugLog = function (message, data) {
    if (console && console.log) {
        const timestamp = new Date().toLocaleTimeString();
        console.log(`[${timestamp}] WbsList: ${message}`, data || '');
    }
};

// ================================================================
// 추가 유틸리티 함수들
// ================================================================

/**
 * 페이지 네비게이션 헬퍼
 * @description 페이지 이동 시 필요한 공통 처리를 수행합니다.
 * @param {number} targetPage - 이동할 페이지 번호
 */
scwin.navigateToPage = function (targetPage) {
    if (targetPage < 1) targetPage = 1;

    dmp_wbsVo.set("pageIndex", String(targetPage));
    $c.sbm.execute(sbm_selectWbsVoList);
};

/**
 * 그리드 새로고침
 * @description 그리드를 새로고침하고 스타일을 다시 적용합니다.
 */
scwin.refreshGrid = function () {
    grd_list.redraw();
    scwin.setProgressStyle();
    scwin.setTaskStatusStyle();
    scwin.setTestStatusStyle();
    scwin.setDelayStatusStyle();
    scwin.setTaskTypeStyle();
};
